{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE snitch_db.maplemonk.tagid_final AS WITH logic_voucher_enriched AS ( SELECT TO_VARCHAR(LOT_NUMBER) AS LOGIC_LOT_NUMBER, UNIQUEKEY, TYPE, ORIGIN, BILL_NO, GRN_NUMBER, DOC_TYPE, QUANTITY, VOUCH_NO, BILL_DATE, TOTAL_TAX, AGENT_NAME, GRN_PREFIX, NET_AMOUNT, VOUCH_CODE, VOUCH_DATE, ACTION_CODE, BRANCH_CODE, TO_PARTY, ACCOUNT_CODE, FROM_PARTY, GROSS_AMOUNT, CURRENCY_NAME, DOC_TYPE_DESC, TAX_REGION_NAME, SKU, CD, CD_PER, CF_1, CF_2, CF_3, GROSS_PUR_AMT, HSN_CODE, ITEMCODE, ITEM_MRP, ITEM_PUR_RATE, ITEM_SALE_RATE, ITEM_SP_RATE_1, ITEM_SP_RATE_2, ITEM_SP_RATE_3, ITEM_SP_RATE_4, ITEM_SP_RATE_5, LOT_CODE, LOT_MRP, PACKNAME, PUR_GROSS_AMT, PUR_MRP, PUR_NET_AMT, PUR_NET_RATE, PUR_ROUND_AMT, PUR_TXN_CODE, ITEM_QUANTITY, RATE, SP_CD, SP_CD_PER, SCHEME_RS, SCHEME_UNIT, TD, TD_PER, TAX_AMT_1, TAX_AMT_3, CASE WHEN GRN_NUMBER IS NOT NULL THEN \'GRN DONE\' ELSE \'PENDING FOR GRN\' END AS PO_GRN_STATUS FROM snitch_db.maplemonk.logic_purchase_voucher ), tagid_filtered AS ( SELECT TO_VARCHAR(CUSTOMER_PURCHASE_ORDER) AS CUSTOMER_PURCHASE_ORDER, TO_VARCHAR(INDENT_NUMBER) AS INDENT_NUMBER, ORDER_CREATION_DATE, APPROVAL_DATE, VENDOR_NAME, TRY_TO_DATE(PO_DATE) AS PO_DATE, EXPECTED_DELIVERY_DATE, SHIPPED_STATUS, DISPATCH_DATE, CURRENT_STATUS, TRY_TO_NUMBER(PO_INITIAL_QTY) AS PO_INITIAL_QTY, BRANCH_NAME, BRANCH_SHORT_NAME, LOT_NUMBER, TXN_CODE, PACKNAME, PRODUCT, COLOR_NO, SKU, LAST_UPDATED_DATE, PRINTING_COMPLETED_DATE, \"Courier Partner\" AS COURIER_PARTNER, \"AWB/LR Number\" AS AWB_LR_NUMBER FROM snitch_db.maplemonk.test_get_orders_dump WHERE NOT ( CURRENT_STATUS = \'Not Ordered Yet\' AND ( PO_DATE IS NULL OR TRY_TO_DATE(PO_DATE) < DATEADD(MONTH, -3, CURRENT_DATE) ) ) ), tagid_agg AS ( SELECT CUSTOMER_PURCHASE_ORDER, MIN(INDENT_NUMBER) AS INDENT_NUMBER, MIN(ORDER_CREATION_DATE) AS ORDER_CREATION_DATE, MIN(APPROVAL_DATE) AS APPROVAL_DATE, MIN(VENDOR_NAME) AS VENDOR_NAME, MIN(PO_DATE) AS PO_DATE, MIN(EXPECTED_DELIVERY_DATE) AS EXPECTED_DELIVERY_DATE, MIN(SHIPPED_STATUS) AS SHIPPED_STATUS, MIN(DISPATCH_DATE) AS DISPATCH_DATE, MIN(CURRENT_STATUS) AS CURRENT_STATUS, SUM(PO_INITIAL_QTY) AS PO_INITIAL_QTY, MIN(BRANCH_NAME) AS BRANCH_NAME, MIN(BRANCH_SHORT_NAME) AS BRANCH_SHORT_NAME FROM tagid_filtered GROUP BY CUSTOMER_PURCHASE_ORDER ), final_joined AS ( SELECT COALESCE(l.LOGIC_LOT_NUMBER, t.CUSTOMER_PURCHASE_ORDER) AS PO_NUMBER, t.CUSTOMER_PURCHASE_ORDER, t.INDENT_NUMBER, t.ORDER_CREATION_DATE, t.APPROVAL_DATE, t.VENDOR_NAME, t.PO_DATE, t.EXPECTED_DELIVERY_DATE, t.SHIPPED_STATUS, t.DISPATCH_DATE, t.CURRENT_STATUS, t.PO_INITIAL_QTY, t.BRANCH_NAME, t.BRANCH_SHORT_NAME, l.PO_GRN_STATUS, l.LOGIC_LOT_NUMBER, l.UNIQUEKEY, l.TYPE, l.ORIGIN, l.BILL_NO, l.GRN_NUMBER, l.GRN_PREFIX, l.VOUCH_NO, l.VOUCH_CODE, l.VOUCH_DATE, l.BILL_DATE, l.DOC_TYPE, l.DOC_TYPE_DESC, l.BRANCH_CODE, l.TO_PARTY, l.FROM_PARTY, l.ACCOUNT_CODE, l.AGENT_NAME, l.CURRENCY_NAME, l.TAX_REGION_NAME, l.QUANTITY, l.ITEM_QUANTITY, l.NET_AMOUNT, l.GROSS_AMOUNT, l.TOTAL_TAX, l.TAX_AMT_1, l.TAX_AMT_3, l.SKU AS LOGIC_SKU, l.ITEMCODE, l.HSN_CODE, l.PACKNAME AS LOGIC_PACKNAME, l.ITEM_MRP, l.ITEM_PUR_RATE, l.ITEM_SALE_RATE, l.RATE, l.PUR_TXN_CODE FROM tagid_agg t LEFT JOIN logic_voucher_enriched l ON t.CUSTOMER_PURCHASE_ORDER = l.LOGIC_LOT_NUMBER ) SELECT * FROM final_joined;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from snitch_db.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            